router.get('/receipts/:number/image', async (req, res) => { 
  const receipt = await Receipt.findOne({ receiptNumber: req.params.number }).populate('donation'); 
  if (!receipt || !receipt.donation) return res.sendStatus(404); 
  const donation = receipt.donation; 
  const dateText = displayDate(donation.date || Date.now());
  const amountWords = amountInWords(donation.amount || 0); 
  
  const html = '<html lang="en"><head><meta charset="UTF-8"><title>Receipt ' + receipt.receiptNumber + '</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:"Segoe UI",sans-serif;background:#f5f5f5;padding:20px}.receipt-container{max-width:800px;margin:0 auto;background:#fff8ed;border:6px solid #d4af37;border-radius:15px;padding:40px;box-shadow:0 8px 16px rgba(94,58,42,.15)}.om{font-size:20px;color:#8d2d24;font-weight:bold;text-align:center}.committee-name{font-size:28px;color:#8d2d24;font-weight:bold;letter-spacing:1px;margin:10px 0;text-align:center}.subtitle{font-size:14px;color:#d4af37;letter-spacing:1px;text-align:center}.receipt-number{text-align:right;font-size:14px;color:#8d2d24;margin:20px 0}.receipt-id{font-weight:bold;color:#a42b1c}.qr-code{width:80px;height:80px;border:2px solid #d4af37;padding:5px;background:white}.content-wrapper{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin:30px 0}.section{padding:20px;border:2px solid #c9a87d;border-radius:8px;background:#faf9f6}.section-title{font-size:14px;font-weight:bold;color:#fff;background:#8d2d24;padding:8px 12px;margin:-20px -20px 15px -20px;display:flex;align-items:center}.field{display:flex;margin:12px 0;font-size:14px}.field-label{font-weight:600;color:#8d2d24;min-width:120px}.amount-box{background:#2d5f3f;color:white;padding:20px;text-align:center;border-radius:12px;margin:25px 0}.amount-box .value{font-size:36px;font-weight:bold;margin:5px 0}.amount-words{font-size:13px;margin-top:8px;font-style:italic;color:#d4af37}.message{background:#f4e8d0;border-left:4px solid #a42b1c;padding:15px;border-radius:4px;font-size:13px;line-height:1.6;margin:20px 0}.generated-info{display:grid;grid-template-columns:1fr 1fr;gap:20px;text-align:center;font-size:12px;margin:20px 0}.info-box{background:#faf9f6;padding:12px;border-radius:6px;border:1px solid #d4af37}.info-label{font-weight:600;color:#8d2d24}.verification{text-align:center;padding:15px;background:#f4e8d0;border-radius:8px;margin:20px 0;font-size:11px}.footer{text-align:center;margin-top:30px;font-size:12px}.footer-text{color:#666;font-size:11px;line-height:1.5}.footer-ornament{color:#d4af37;font-size:16px;margin:15px 0;letter-spacing:3px;text-align:center}</style></head><body><div class="receipt-container"><div class="om">॥ श्री गणेशाय नमः ॥</div><div style="text-align:center"><div style="text-align:right;margin-bottom:30px">' + (receipt.qrData ? '<img src="' + receipt.qrData + '" class="qr-code" alt="QR">' : '') + '<div style="font-size:11px;color:#666;margin-top:5px">Scan to Verify</div></div><div class="committee-name">SD COLONY GANESH UTSAV COMMITTEE</div><div class="subtitle">OFFICIAL DONATION RECEIPT</div></div><div class="receipt-number"><div>Date: <strong>' + dateText + '</strong></div><div>Receipt No: <span class="receipt-id">' + receipt.receiptNumber + '</span></div></div><div class="content-wrapper"><div class="section"><div class="section-title">👤 DONOR DETAILS</div><div class="field"><div class="field-label">Donor Name:</div><div>' + svgText(donation.donorName || 'N/A') + '</div></div><div class="field"><div class="field-label">Flat Number:</div><div>' + svgText(donation.flatNumber || 'N/A') + '</div></div><div class="field"><div class="field-label">Mobile Number:</div><div>' + svgText(donation.mobile || 'N/A') + '</div></div></div><div class="section"><div class="section-title">🎁 CONTRIBUTION DETAILS</div><div class="field"><div class="field-label">Amount Donated:</div><div style="font-weight:bold">₹ ' + Number(donation.amount || 0).toLocaleString('en-IN') + '/-</div></div><div class="field"><div class="field-label">Payment Mode:</div><div>' + svgText(donation.paymentMode || 'Cash') + '</div></div></div></div><div class="amount-box"><div style="font-size:12px;letter-spacing:1px;opacity:.9">AMOUNT DONATED</div><div class="value">₹ ' + Number(donation.amount || 0).toLocaleString('en-IN') + '/-</div><div style="font-size:12px;letter-spacing:1px;margin-top:8px;opacity:.9">AMOUNT IN WORDS</div><div class="amount-words">' + amountWords + '</div></div><div class="message"><strong>🙏 Ganpati Bappa Morya!</strong><br>Your generous contribution helps us celebrate Lord Ganesha\'s blessings, unity, and cultural heritage. We sincerely appreciate your support.</div><div class="generated-info"><div class="info-box"><div class="info-label">GENERATED ON</div><div>' + new Date(receipt.createdAt).toLocaleDateString('en-IN') + '</div><div style="font-size:11px;color:#666">' + new Date(receipt.createdAt).toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' }) + '</div></div><div class="info-box"><div class="info-label">VERIFIED BY</div><div>SD Colony<br>Ganesh Utsav<br>Committee</div></div></div><div class="verification"><strong>✓ This is a computer-generated receipt</strong><br>and does not require a physical signature.<br>For any queries contact: +91 98765 43210</div><div class="footer"><div style="font-weight:bold;margin:15px 0">☺️ Committee Representative</div><div class="footer-ornament">॥ गणपति बप्पा मोरया | मंगलमूर्ती मोरया ॥</div><div class="footer-text"><strong>Thank you for supporting SD Colony Ganesh Utsav Committee.</strong><br>May this festive season bring happiness, prosperity, and success to you and your family.</div></div></div></body></html>';
  
  res.set('Content-Type', 'text/html; charset=utf-8').send(html); 
});

router.get('/receipts/:number/public-pdf', async (req, res) => { const receipt = await Receipt.findOne({ receiptNumber: req.params.number }).populate('donation'); const donation = receipt?.donation || await Donation.findOne({ receiptNumber: req.params.number }); if (!donation) return res.sendStatus(404); const number = receipt?.receiptNumber || donation.receiptNumber || req.params.number; const doc = new PDFDocument({ margin: 50 }); res.attachment(receiptDownloadName(donation, number, 'pdf')); doc.pipe(res); doc.fontSize(22).fillColor('#8d2d24').text(process.env.COMMITTEE_NAME || 'SD Colony Ganesh Utsav Committee', { align: 'center' }); doc.moveDown().fontSize(15).fillColor('#222').text(`Receipt No: ${number}`).text(`Donor: ${donation.donorName}`).text(`Flat Number: ${donation.flatNumber || '--'}`).text(`Mobile Number: ${donation.mobile || '--'}`).text(`Amount: Rs. ${donation.amount}`).text(`Payment Mode: ${donation.paymentMode || 'Cash'}`).text(`Date: ${new Date(donation.createdAt || donation.date).toLocaleString('en-IN')}`); doc.end(); });
router.use(auth);
router.put('/settings/contact', async (req, res) => res.json(await SiteSettings.findOneAndUpdate({ key: 'contact' }, { key: 'contact', contactEmail: req.body.contactEmail, phone1: req.body.phone1, phone2: req.body.phone2, upiId: req.body.upiId }, { upsert: true, new: true, runValidators: true })));
router.delete('/settings/upi', async (_req, res) => { await SiteSettings.findOneAndUpdate({ key: 'contact' }, { $set: { upiId: '' } }); res.sendStatus(204); });
router.put('/auth/password', async (req, res) => { const { currentPassword, newPassword, confirmPassword } = req.body; if (!currentPassword || !newPassword || newPassword !== confirmPassword || newPassword.length < 8) return res.status(400).json({ message: 'Use a matching password of at least 8 characters.' }); const user = await User.findById(req.user.id); if (!user || !(await bcrypt.compare(currentPassword, user.password))) return res.status(401).json({ message: 'Current password is incorrect.' }); user.password = await bcrypt.hash(newPassword, 12); await user.save(); res.json({ message: 'Password updated successfully.' }); });
const resources = [ ['members', CommitteeMember], ['events', Event] ];
resources.forEach(([name, Model]) => { router.get(`/${name}`, async (_r, res) => res.json(await Model.find().sort('-createdAt'))); router.post(`/${name}`, async (req, res) => res.status(201).json(await Model.create(req.body))); router.put(`/${name}/:id`, async (req, res) => res.json(await Model.findByIdAndUpdate(req.params.id, req.body, { new: true, runValidators: true }))); router.delete(`/${name}/:id`, async (req, res) => { await Model.findByIdAndDelete(req.params.id); res.sendStatus(204); }); });
router.get('/donations', async (_r, res) => res.json(await Donation.find().sort('-date')));
router.post('/donations', async (req, res) => { const year = new Date().getFullYear(); let nextNum = 1; const lastDonation = await Donation.findOne({ receiptNumber: new RegExp(`^GU-${year}-`) }).sort({ receiptNumber: -1 }); if (lastDonation) { const match = lastDonation.receiptNumber.match(/GU-\d+-(\d+)/); if (match) nextNum = parseInt(match[1]) + 1; } const receiptNumber = `GU-${year}-${String(nextNum).padStart(4, '0')}`; const donation = await Donation.create({ ...req.body, receiptNumber }); const qrData = await QRCode.toDataURL(`${process.env.COMMITTEE_NAME || 'SD Colony Ganesh Utsav Committee'} | ${receiptNumber} | Rs. ${donation.amount}`); await Receipt.findOneAndUpdate({ receiptNumber }, { receiptNumber, donation: donation._id, qrData }, { upsert: true, new: true }); res.status(201).json(donation); });
router.put('/donations/:id', async (req, res) => res.json(await Donation.findByIdAndUpdate(req.params.id, req.body, { new: true, runValidators: true })));
router.delete('/donations/:id', async (req, res) => { const donation = await Donation.findByIdAndDelete(req.params.id); if (!donation) return res.sendStatus(404); await Receipt.deleteOne({ donation: donation._id }); res.sendStatus(204); });
router.get('/expenses', async (_req, res) => res.json(await Expense.find().sort('-date')));
router.post('/expenses', billUpload.single('bill'), async (req, res) => { const expense = await Expense.create({ name: req.body.name, amount: req.body.amount, date: req.body.date, paymentMode: req.body.paymentMode, ...(req.file ? { billFilename: req.file.filename, billOriginalName: req.file.originalname, billPath: `/api/expenses/${req.file.filename}/bill`, billMimeType: req.file.mimetype } : {}) }); res.status(201).json(expense); });
router.put('/expenses/:id', async (req, res) => res.json(await Expense.findByIdAndUpdate(req.params.id, { name: req.body.name, amount: req.body.amount, date: req.body.date, paymentMode: req.body.paymentMode }, { new: true, runValidators: true })));
router.delete('/expenses/:id', async (req, res) => { const expense = await Expense.findByIdAndDelete(req.params.id); if (!expense) return res.sendStatus(404); if (expense.billFilename) { const billPath = path.join(uploadDir, expense.billFilename); if (fs.existsSync(billPath)) fs.unlinkSync(billPath); } res.sendStatus(204); });
router.get('/expenses/:id/bill', async (req, res) => { const expense = await Expense.findById(req.params.id); if (!expense?.billFilename) return res.sendStatus(404); res.sendFile(path.join(uploadDir, expense.billFilename)); });
router.post('/expenses/:id/bill', billUpload.single('bill'), async (req, res) => { const expense = await Expense.findById(req.params.id); if (!expense || !req.file) return res.sendStatus(404); if (expense.billFilename) { const oldPath = path.join(uploadDir, expense.billFilename); if (fs.existsSync(oldPath)) fs.unlinkSync(oldPath); } expense.billFilename = req.file.filename; expense.billOriginalName = req.file.originalname; expense.billPath = `/api/expenses/${expense._id}/bill`; expense.billMimeType = req.file.mimetype; await expense.save(); res.json(expense); });
router.post('/gallery', upload.array('images', 20), async (req, res) => { const items = await Promise.all(req.files.map((file, index) => Gallery.create({ title: req.body.title || file.originalname.replace(/\.[^.]+$/, ''), caption: req.body.caption || '', displayOrder: Number(req.body.displayOrder || index), filename: file.filename, originalName: file.originalname, path: `/uploads/${file.filename}` }))); res.status(201).json(items); });
